head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst72110";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — invstgStatCode

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst72110.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_if_17", fn: function(){ return ((((dma_listInvstgProc.get("prelmInvstgProgStatCd13") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd13"); })())) && typeof ((dma_listInvstgProc.get("prelmInvstgProgStatCd13") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd13"); })())).getRowCount === 'function' ? ((dma_listInvstgProc.get("prelmInvstgProgStatCd13") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd13"); })())).getRowCount() : ((((dma_listInvstgProc.get("prelmInvstgProgStatCd13") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd13"); })())) == null) ? 0 : (((dma_listInvstgProc.get("prelmInvstgProgStatCd13") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd13"); })())).length || 0))) === 8); } }, { id: "if_invstgStatCode", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") >=13); } }, { id: "c_if_26_r1", fn: function(){ return ((((dma_listInvstgProc.get("prelmInvstgProgStatCd14") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd14"); })())) && typeof ((dma_listInvstgProc.get("prelmInvstgProgStatCd14") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd14"); })())).getRowCount === 'function' ? ((dma_listInvstgProc.get("prelmInvstgProgStatCd14") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd14"); })())).getRowCount() : ((((dma_listInvstgProc.get("prelmInvstgProgStatCd14") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd14"); })())) == null) ? 0 : (((dma_listInvstgProc.get("prelmInvstgProgStatCd14") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd14"); })())).length || 0))) === 8); } }, { id: "if_invstgStatCode_2_r1", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") >= 14); } }, { id: "c_if_35_r2", fn: function(){ return ((((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())) && typeof ((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())).getRowCount === 'function' ? ((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())).getRowCount() : ((((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())) == null) ? 0 : (((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())).length || 0))) === 8); } }, { id: "if_invstgStatCode_3_r2", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") >= 97); } }, { id: "c_when_5", fn: function(){ return ((dma_corpOvrvw.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.spotIsuTrdMktTpCd"); })()) === '6'); } }, { id: "c_otherwise_42", fn: function(){ return (!(((dma_corpOvrvw.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.spotIsuTrdMktTpCd"); })()) === '6'))); } }, { id: "c_if_54", fn: function(){ return ((((dma_listInvstgProc.get("prelmInvstgProgStatCd01") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd01"); })())) && typeof ((dma_listInvstgProc.get("prelmInvstgProgStatCd01") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd01"); })())).getRowCount === 'function' ? ((dma_listInvstgProc.get("prelmInvstgProgStatCd01") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd01"); })())).getRowCount() : ((((dma_listInvstgProc.get("prelmInvstgProgStatCd01") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd01"); })())) == null) ? 0 : (((dma_listInvstgProc.get("prelmInvstgProgStatCd01") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd01"); })())).length || 0))) === 8); } }, { id: "if_invstgStatCode_4", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") >= 1); } }, { id: "c_if_63_r1", fn: function(){ return ((((dma_listInvstgProc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd07"); })())) && typeof ((dma_listInvstgProc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd07"); })())).getRowCount === 'function' ? ((dma_listInvstgProc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd07"); })())).getRowCount() : ((((dma_listInvstgProc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd07"); })())) == null) ? 0 : (((dma_listInvstgProc.get("prelmInvstgProgStatCd07") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd07"); })())).length || 0))) === 8); } }, { id: "if_invstgStatCode_5_r1", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") >= 7); } }, { id: "c_if_72_r2", fn: function(){ return ((((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())) && typeof ((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())).getRowCount === 'function' ? ((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())).getRowCount() : ((((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())) == null) ? 0 : (((dma_listInvstgProc.get("prelmInvstgProgStatCd97") ?? (() => { throw new Error("unresolved:" + "listInvstgProc.prelmInvstgProgStatCd97"); })())).length || 0))) === 8); } }, { id: "if_invstgStatCode_6_r2", fn: function(){ return ((dma_pageContext.get("invstgStatCode") ?? "") >= 97); } }, { id: "img_95", fn: function(){ return ((dma_corpOvrvw.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "img_97", fn: function(){ return ((dma_corpOvrvw.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.spotIsuTrdMktTpCd"); })()) === '2'); } }, { id: "img_99", fn: function(){ return ((dma_corpOvrvw.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.spotIsuTrdMktTpCd"); })()) === '6'); } }, { id: "c_when_101_txt", fn: function(){ return (!(String(((dma_corpOvrvw.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.comAbbrv"); })())) == null ? '' : ((dma_corpOvrvw.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.comAbbrv"); })()))).length === 0)); } }, { id: "c_when_102_txt", fn: function(){ return (!(String(((dma_corpOvrvw.get("comNm") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.comNm"); })())) == null ? '' : ((dma_corpOvrvw.get("comNm") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.comNm"); })()))).length === 0)); } }, { id: "c_when_114_txt", fn: function(){ return ((dma_corpOvrvw.get("dpFromEmpCnt") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.dpFromEmpCnt"); })()) === '0'); } }, { id: "c_otherwise_115", fn: function(){ return (!(((dma_corpOvrvw.get("dpFromEmpCnt") ?? (() => { throw new Error("unresolved:" + "corpOvrvw.dpFromEmpCnt"); })()) === '0'))); } }, { id: "btn_FileDown", fn: function(){ return (!(String(((dma_pubofrOvrwv.get("attachFileNm") ?? (() => { throw new Error("unresolved:" + "pubofrOvrwv.attachFileNm"); })())) == null ? '' : ((dma_pubofrOvrwv.get("attachFileNm") ?? (() => { throw new Error("unresolved:" + "pubofrOvrwv.attachFileNm"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb5", fn: function () { return String(dma_corpOvrvw.get("dpFromEmpCnt")) + " 명"; } },
        { childId: "__rb10", fn: function () { return String(dma_corpOvrvw.get("dpFromAcntclsMmdd")) + " 월"; } },
        { childId: "__rb17", fn: function () { return String(dma_corpOvrvw.get("dpFromLgshrhdRto")) + " %"; } },
        { childId: "btn_FileDown", fn: function () { return String(dma_pubofrOvrwv.get("attachFileNm")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $("#dialog-loading").hide();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst72110.onpageload' }); }
};

// [A] 초기 목록 미해결 — jlddst72110: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_FileDown_onclick
 * @description btn_FileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_FileDown_onclick = function(e){
    try {
        scwin.fileDown('' + dma_pubofrOvrwv.get("bzProcsNo") + '','' + dma_pubofrOvrwv.get("attachFileNm") + ''); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst72110.btn_FileDown_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {*} val1 val1
 * @param {*} val2 val2
 * @returns {void}
 * @hidden N
 */
scwin.fileDown = function (val1, val2) {
    $c.util.getComponent("ipt_bzProcsNo").setValue(val1);
    $c.util.getComponent("ipt_attachFileNm").setValue(val2);
    $("#fileDownForm").submit();
};

/**
 * @method
 * @name fnPopClose
 * @description fn Pop Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnPopClose = function () {
    $c.win.closePopup();
};
